using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleCorruptedAnimals", menuName = "Data/Battle/Corrupted Animals/Battle Corrupted Animals")]
public class BattleCorruptedAnimals : ScriptableObject
{
	[Header("Corrupted Animals")]
	public bool Package;

	[HideIf("Package")]
	public CorruptedAnimalData[] CorruptedAnimals;

	[ShowIf("Package")]
	public BattleCorruptedAnimals battleCorruptedAnimalsPackage;

	[Header("Debug")]
	public bool DebugBattle;

	public bool IsCorruptionSourceBattle()
	{
		for (int i = 0; i < CorruptedAnimals.Length; i++)
		{
			if (CorruptedAnimals[i].CorruptionSource)
			{
				return true;
			}
		}
		return false;
	}

	public bool IsCorruptionSourceBattleIgnoreCorruptionSourcePositioning()
	{
		for (int i = 0; i < CorruptedAnimals.Length; i++)
		{
			if (CorruptedAnimals[i].CorruptionSource && CorruptedAnimals[i].IgnoreCorruptionSourcePositioning)
			{
				return true;
			}
		}
		return false;
	}

	public bool IsAlwaysSpawnInTheMiddleBattle()
	{
		for (int i = 0; i < CorruptedAnimals.Length; i++)
		{
			if (CorruptedAnimals[i].AlwaysSpawnInTheMiddle)
			{
				return true;
			}
		}
		return false;
	}
}
